import networkx as nx
import json
import os
import math
import heapq
import pandas as pd
from typing import Dict, List


def _edge_cost(data):
    value = data.get("cost")
    if value is None:
        return None
    try:
        value = float(value)
        return value if math.isfinite(value) and value >= 0 else None
    except (TypeError, ValueError):
        return None


def _edge_union_cost(G, edges):
    return sum(_edge_cost(G[u][v]) or 0.0 for u, v in edges)


def _shortest_paths(h, src, dsts):
    paths = {}
    for dst in dsts:
        paths[dst] = nx.dijkstra_path(h, src, dst, weight="cost")
    return paths


def _paths_to_edges(paths):
    result = set()
    for path in paths.values():
        result.update(zip(path, path[1:]))
    return result


def _greedy_tree(h, src, terminals, orders):
    """Bounded fallback for larger terminal sets."""
    best_edges = None
    best_paths = None
    best_cost = float("inf")

    for order in orders:
        used = set()
        paths = {}
        feasible = True

        for dst in order:
            def marginal(u, v, data):
                if (u, v) in used:
                    return 0.0
                c = _edge_cost(data)
                return float("inf") if c is None else c

            try:
                path = nx.dijkstra_path(h, src, dst, weight=marginal)
            except (nx.NetworkXNoPath, nx.NodeNotFound):
                feasible = False
                break
            paths[dst] = path
            used.update(zip(path, path[1:]))

        if feasible:
            value = _edge_union_cost(h, used)
            if value < best_cost:
                best_cost = value
                best_edges = used
                best_paths = paths

    return best_edges, best_paths


def _frontier_multicast_edges(h, src, terminals):
    """Build a bounded one- or two-frontier multicast tree with shared branches."""
    terminals = list(dict.fromkeys(terminals))
    if not terminals:
        return set()

    try:
        source_dist, source_paths = nx.single_source_dijkstra(
            h, src, weight="cost"
        )
    except (nx.NetworkXNoPath, nx.NodeNotFound):
        return None

    reverse = h.reverse(copy=True)
    reverse_dist = {}
    reverse_paths = {}
    for terminal in terminals:
        try:
            distances, paths = nx.single_source_dijkstra(
                reverse, terminal, weight="cost"
            )
        except (nx.NetworkXNoPath, nx.NodeNotFound):
            distances, paths = {}, {}
        reverse_dist[terminal] = distances
        reverse_paths[terminal] = paths

    # Rank joins by source cost plus the cheapest reachable terminal frontier.
    ranked = []
    for node in h.nodes():
        if node not in source_dist:
            continue
        reachable = [
            reverse_dist[terminal][node]
            for terminal in terminals
            if node in reverse_dist[terminal]
        ]
        if reachable:
            ranked.append((source_dist[node] + sum(reachable), node))
    joins = [node for _, node in sorted(ranked)[:12]]
    if not joins:
        return None

    def path_edges(path):
        return set(zip(path, path[1:]))

    def build(join_nodes):
        edges = set()
        for join in join_nodes:
            trunk = source_paths.get(join)
            if trunk is None:
                return None
            edges.update(path_edges(trunk))

        assignments = {join: [] for join in join_nodes}
        for terminal in terminals:
            choices = []
            for join in join_nodes:
                reverse_path = reverse_paths[terminal].get(join)
                if reverse_path is None:
                    continue
                forward_path = list(reversed(reverse_path))
                choices.append(
                    (
                        _edge_union_cost(h, path_edges(forward_path)),
                        join,
                        forward_path,
                    )
                )
            if not choices:
                return None
            _, join, path = min(choices, key=lambda item: item[0])
            assignments[join].append((terminal, path))

        # Preserve at most six shared first-hop groups per join.  Any
        # remaining groups are still emitted as valid terminal branches.
        for join, assigned in assignments.items():
            groups = {}
            for terminal, path in assigned:
                first_hop = path[1] if len(path) > 1 else terminal
                groups.setdefault(first_hop, []).append(path)

            ranked_groups = sorted(
                groups.values(),
                key=lambda paths: min(
                    _edge_union_cost(h, path_edges(path)) for path in paths
                ),
            )
            for group in ranked_groups[:6]:
                for path in group:
                    edges.update(path_edges(path))
            for group in ranked_groups[6:]:
                for path in group:
                    edges.update(path_edges(path))
        return edges

    candidates = [(join,) for join in joins]
    candidates.extend(
        (joins[i], joins[j])
        for i in range(len(joins))
        for j in range(i + 1, len(joins))
    )

    best_edges = None
    best_cost = float("inf")
    for candidate in candidates:
        edges = build(candidate)
        if edges is None:
            continue
        cost = _edge_union_cost(h, edges)
        if cost < best_cost:
            best_cost = cost
            best_edges = edges
    return best_edges


def _legacy_directed_steiner_edges(h, src, terminals):
    """
    Exact directed Steiner DP retained only as a compatibility fallback.
    dp[mask][v] is represented by a cost dictionary and traceback dictionary.
    """
    terminals = list(dict.fromkeys(terminals))
    k = len(terminals)
    if k == 0:
        return set()
    if k > 7:
        return None

    nodes = list(h.nodes())
    incoming = {v: [] for v in nodes}
    for u, v, data in h.edges(data=True):
        c = _edge_cost(data)
        if c is not None:
            incoming[v].append((u, c))

    full = (1 << k) - 1
    dp = [dict() for _ in range(full + 1)]
    choice = [dict() for _ in range(full + 1)]

    for mask in range(1, full + 1):
        initial = {}
        initial_choice = {}

        if mask & (mask - 1) == 0:
            terminal = terminals[mask.bit_length() - 1]
            initial[terminal] = 0.0
            initial_choice[terminal] = ("terminal",)
        else:
            sub = (mask - 1) & mask
            while sub:
                other = mask ^ sub
                if other and sub < other:
                    common = set(dp[sub]).intersection(dp[other])
                    for v in common:
                        value = dp[sub][v] + dp[other][v]
                        if value < initial.get(v, float("inf")):
                            initial[v] = value
                            initial_choice[v] = ("merge", sub)
                sub = (sub - 1) & mask

        # Multi-source reverse Dijkstra computes min_w c(v,w) + initial[w].
        dist = dict(initial)
        trace = dict(initial_choice)
        heap = [(value, v) for v, value in initial.items()]
        heapq.heapify(heap)

        while heap:
            value, v = heapq.heappop(heap)
            if value != dist.get(v):
                continue
            for u, edge_cost in incoming.get(v, []):
                candidate = value + edge_cost
                if candidate < dist.get(u, float("inf")):
                    dist[u] = candidate
                    trace[u] = ("edge", v)
                    heapq.heappush(heap, (candidate, u))

        dp[mask] = dist
        choice[mask] = trace

    if src not in dp[full]:
        return None

    selected = set()
    visiting = set()

    def recover(mask, v):
        state = (mask, v)
        if state in visiting:
            return
        visiting.add(state)
        action = choice[mask][v]
        if action[0] == "edge":
            w = action[1]
            selected.add((v, w))
            recover(mask, w)
        elif action[0] == "merge":
            left = action[1]
            recover(left, v)
            recover(mask ^ left, v)
        visiting.remove(state)

    recover(full, src)
    return selected


def search_algorithm(src, dsts, G, num_partitions):
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))

    # Ignore unusable cost edges rather than allowing Dijkstra comparisons with None.
    invalid = [(u, v) for u, v, data in h.edges(data=True) if _edge_cost(data) is None]
    h.remove_edges_from(invalid)

    bc_topology = BroadCastTopology(src, dsts, num_partitions)
    unique_dsts = list(dict.fromkeys(dsts))

    try:
        baseline_paths = _shortest_paths(h, src, unique_dsts)
    except (nx.NetworkXNoPath, nx.NodeNotFound):
        # Preserve the original behavior for malformed/unreachable evaluator inputs.
        baseline_paths = {}
        for dst in unique_dsts:
            try:
                baseline_paths[dst] = nx.dijkstra_path(h, src, dst, weight="cost")
            except (nx.NetworkXNoPath, nx.NodeNotFound):
                baseline_paths[dst] = []

    baseline_edges = _paths_to_edges(baseline_paths)
    selected_edges = baseline_edges

    # Evaluate up to twelve independently ranked replication joins and every
    # bounded two-join combination.  The shortest-path union remains the
    # incumbent when a frontier candidate is unreachable or more expensive.
    frontier_edges = _frontier_multicast_edges(h, src, unique_dsts)
    if (
        frontier_edges is not None
        and _edge_union_cost(h, frontier_edges)
        < _edge_union_cost(h, selected_edges)
    ):
        selected_edges = frontier_edges

    tree_graph = nx.DiGraph()
    tree_graph.add_nodes_from(h.nodes())
    for u, v in selected_edges:
        tree_graph.add_edge(u, v, **G[u][v])

    final_paths = {}
    for dst in unique_dsts:
        try:
            final_paths[dst] = nx.dijkstra_path(tree_graph, src, dst, weight="cost")
        except (nx.NetworkXNoPath, nx.NodeNotFound):
            final_paths[dst] = baseline_paths.get(dst, [])

    for dst in dsts:
        path = final_paths.get(dst, [])
        edges = [[u, v, G[u][v]] for u, v in zip(path, path[1:])]
        for partition in range(bc_topology.num_partitions):
            bc_topology.set_dst_partition_paths(dst, partition, list(edges))

    return bc_topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src
        self.dsts = dsts
        self.num_partitions = num_partitions
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        self.paths[dst][str(partition)] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)


def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(
            row["src_region"],
            row["dst_region"],
            cost=None,
            throughput=num_vms * row["throughput_sent"] / 1e9,
        )

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    no_cost_pairs = []
    for edge in G.edges.data():
        edge_src, edge_dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((edge_src, edge_dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G

